    "@iconify-json/lucide": "^1.2.0",
    "@nuxt/ui": "4.12.0",
    "nuxt": "4.6.3",
    "tailwindcss": "^4.1.0"
  },
  "devDependencies": {
    "@nuxt/eslint": "1.15.0",
    "@types/node": "^26.6.6",
    "eslint": "^10.14.0",
    "eslint-config-prettier": "^10.1.8",
